#include <cmath>
#include <ctime>
using namespace std;

int main()
{
    // 1. read radius and length
    double r, length;
    cin >> r >> length;
    // 2. reject dimensions that cannot form a cylinder
    if (r <= 0 || length <= 0)
    {
        cout << "Invalid dimensions" << endl;
        return 0;
